import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Container, Row, Col, Card } from "react-bootstrap";

function Dashboard() {
  const [stats, setStats] = useState({ capacity: "...", revenue: "...", errors: 0, followers: 0 });
  const [chartData, setChartData] = useState({ labels: [], series: [] });

  useEffect(() => {
    // ดึงตัวเลข
    fetch('http://localhost:3000/api/dashboard-stats')
      .then(res => res.json()).then(data => setStats(data));

    // ดึงกราฟ
    fetch('http://localhost:3000/api/chart-data')
      .then(res => res.json()).then(data => setChartData(data));
  }, []);

  return (
    <Container fluid>
      <Row>
        <Col lg="3" sm="6">
          <Card className="card-stats">
            <Card.Body>
              <Row>
                <Col xs="5"><div className="icon-big text-center icon-warning"><i className="nc-icon nc-bus-front-12 text-warning"></i></div></Col>
                <Col xs="7"><div className="numbers"><p className="card-category">Bus Stops</p><Card.Title as="h4">{stats.capacity}</Card.Title></div></Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
        {/* ... (การ์ดอื่นๆ ใส่ตามเดิมได้) ... */}
      </Row>

      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">Passenger Traffic</Card.Title>
              <p className="card-category">Number of passengers per hour</p>
            </Card.Header>
            <Card.Body>
              <div className="ct-chart" id="chartHours">
                {/* กราฟเส้นแสดงข้อมูลจริง */}
                <ChartistGraph
                  data={chartData}
                  type="Line"
                  options={{
                    low: 0,
                    showArea: false,
                    height: "245px",
                    axisX: { showGrid: false },
                    lineSmooth: true,
                    showLine: true,
                    showPoint: true,
                    fullWidth: true,
                    chartPadding: { right: 50 }
                  }}
                />
              </div>
            </Card.Body>
            <Card.Footer>
              <div className="stats"><i className="fas fa-history"></i> Updated from Database</div>
            </Card.Footer>
          </Card>
        </Col>
      </Row>
    </Container>
  );
}

export default Dashboard;
